import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'

import styles from './DisconnectedAgentsCounter.module.css'

type Props = {
  counterClassName?: string
  count: number
}
export default function DisconnectedAgentsCounter({count, counterClassName}: Props) {
  return (
    <Tooltip title={count > 0 ? `${count} disconnected` : 'Disconnected'}>
      <SvgIcon
        className={styles.icon}
        icon="disconnected"
        title="disconnected"
        data-test-disconnected-agents-counter={'icon'}
      />
      <span
        className={classNames(styles.counter, counterClassName)}
        data-test-disconnected-agents-counter={'count'}
      >
        {count}
      </span>
    </Tooltip>
  )
}
