import type {KeyValue} from '@jetbrains/teamcity-ui/dist/utils'
import classNames from 'classnames'
import * as React from 'react'

import {noop} from '../../../../../../utils/empty'
import MatchingItem from '../../../../../common/MatchingItem/MatchingItem'
import SidebarLink from '../../../../../common/Sidebar/SidebarLink/SidebarLink'
import type {AgentsTreeItemFolder} from '../../AgentsSidebar.types'
import BusyAgentsCounter from '../../BusyAgentsCounter/BusyAgentsCounter'
import DisconnectedAgentsCounter from '../../DisconnectedAgentsCounter/DisconnectedAgentsCounter'
import {getAgentsTreeSearchState, getIsSearching} from '../../selectors/getExpand'

import styles from './AgentFolder.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = AgentsTreeItemFolder & {
  className?: string | undefined
  style?: KeyValue<string, string | number>
  onToggleExpand?: () => unknown
  ellipsisRef?: React.Ref<HTMLDivElement>
}
export default React.memo(function AgentFolder({
  href,
  title,
  count,
  busyCount,
  disconnectedCount,
  className,
  style,
  matching,
  onToggleExpand,
  ellipsisRef,
}: Props) {
  const {searchQuery} = useAppSelector(getAgentsTreeSearchState)
  const isSearching = useAppSelector(getIsSearching)

  const tail = (
    <>
      {disconnectedCount > 0 && (
        <DisconnectedAgentsCounter
          counterClassName={classNames({
            [styles.counter]: isSearching,
          })}
          count={disconnectedCount}
        />
      )}
    </>
  )

  const content = (
    <>
      {matching === true ? (
        <MatchingItem searchQuery={searchQuery}>{title}</MatchingItem>
      ) : (
        <span>{title}</span>
      )}
      <BusyAgentsCounter
        busyCount={busyCount}
        disconnectedCount={disconnectedCount}
        count={count}
      />
    </>
  )

  if (href) {
    return (
      <SidebarLink
        to={href}
        className={className}
        style={style}
        tail={tail}
        tailClassName={styles.tailLink}
        tabIndex={-1}
        aria-label={title}
        ellipsisRef={ellipsisRef}
      >
        {content}
      </SidebarLink>
    )
  }

  return (
    <div
      role="button"
      tabIndex={-1} // because the outer element SidebarItem_itemWrapper has focus now, the keys don't open
      className={styles.container}
      onClick={onToggleExpand}
      onKeyDown={noop}
    >
      {content}
      <div className={styles.tail}>{tail}</div>
    </div>
  )
})
