import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {memo, useCallback} from 'react'

import {dialog} from '../../../../../slices'
import {DialogType} from '../../../../../types'
import {FAVORITE_DIALOG_SIDEBAR_ID} from '../../AgentPoolsFavoritePage/Dialog/AgentPoolsFavoriteDialog.consts'

import {useAppDispatch} from 'src/hooks/react-redux'

interface Props {
  className?: string
}
const openEditDialog = () =>
  dialog.actions.open(FAVORITE_DIALOG_SIDEBAR_ID, DialogType.FAVORITE_AGENT_POOLS)

function AgentsSidebarEditFavorite(props: Props) {
  const {className} = props
  const dispatch = useAppDispatch()
  const openDialog = useCallback(() => dispatch(openEditDialog()), [dispatch])

  return (
    <Tooltip title={'Edit favorites'} className={className}>
      <IconButton icon="pencil" onClick={openDialog} title={''} aria-label={'Edit favorites'} />
    </Tooltip>
  )
}

export default memo(AgentsSidebarEditFavorite)
