import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import classNames from 'classnames'

import styles from './BusyAgentsCounter.module.css'

type Props = {
  busyCount: number
  disconnectedCount: number
  count: number
  className?: string
}
export default function BusyAgentsCounter({
  busyCount,
  disconnectedCount,
  count,
  className = '',
}: Props) {
  const connectedCount = count - disconnectedCount
  const hasBusyCount = busyCount > 0
  const hasConnectedCount = busyCount < connectedCount
  const showDivider = hasBusyCount && hasConnectedCount

  return (
    <>
      {hasBusyCount || hasConnectedCount ? (
        <Tooltip
          title={
            hasBusyCount && hasConnectedCount
              ? `${busyCount} out of ${count} currently running builds`
              : `${busyCount} currently running builds`
          }
        >
          <span className={classNames(styles.agentsCounter, className)}>
            {busyCount > 0 ? (
              <span className={styles.busyAgentsCounter} data-test-busy-agents-counter={'count'}>
                {busyCount}
              </span>
            ) : null}
            {showDivider ? '/' : null}
            {hasConnectedCount ? connectedCount : null}
          </span>
        </Tooltip>
      ) : null}
    </>
  )
}
