import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import type {HTMLAttributes} from 'react'

import type {OSType} from '../../../../../types'
import {osIconMap} from '../../../../common/AgentLink/AgentLink'
import MatchingTitle, {MatchingHighlight} from '../../../../common/MatchingItem/MatchingItem'

import styles from './LinearAgent.module.css'

type Props = HTMLAttributes<HTMLDivElement> & {
  title?: string
  cloud?: boolean
  connected?: boolean | null
  enabled?: boolean | null
  osType?: OSType | null | undefined
  matching?: boolean
  searchQuery?: string
  ref?: React.Ref<HTMLSpanElement>
}
export default function LinearAgent({
  title,
  cloud,
  matching,
  className,
  connected,
  enabled,
  osType,
  searchQuery,
  ref,
  ...htmlProps
}: Props) {
  const icon = osType != null ? osIconMap[osType] : null

  return (
    <span
      className={classNames(className, {
        [styles.disconnected]: connected === false,
        [styles.disabled]: enabled === false,
      })}
      ref={ref}
      {...htmlProps}
    >
      {icon != null && (
        <SvgIcon
          className={classNames(styles.icon, osType === 'macOS' && styles.macOs)}
          icon={icon}
          data-test-sidebar-agent={'os-icon'}
        />
      )}
      {cloud === true && matching === true ? (
        <MatchingHighlight>{title}</MatchingHighlight>
      ) : (
        <MatchingTitle searchQuery={searchQuery}>{title}</MatchingTitle>
      )}
      {connected === false ? (
        <>
          {' '}
          <SvgIcon className={styles.disconnectedIcon} icon="disconnected" title="disconnected" />
        </>
      ) : null}
    </span>
  )
}
