import classNames from 'classnames'

import styles from './UnauthorizedAgentsCounter.module.css'

type Props = {
  counterClassName?: string
  count: number
}
export default function UnauthorizedAgentsCounter({count, counterClassName}: Props) {
  return (
    <span
      className={classNames(styles.counter, counterClassName)}
      data-test-unauthorized-agents-counter={'count'}
    >
      {count}
    </span>
  )
}
