import cn from 'classnames'
import type * as React from 'react'
import {Link} from 'react-router'

import styles from './SidebarLink.module.css'

type ActiveLinkProps = React.ComponentProps<typeof Link> & {
  tailClassName?: string
  tail?: React.ReactNode
  ellipsisRef?: React.Ref<HTMLDivElement>
  needsOffsetForChevron?: boolean
  contentClassName?: string
}

type InctiveLinkProps = React.HTMLAttributes<HTMLDivElement> & {
  tailClassName?: string
  tail?: React.ReactNode
  ellipsisRef?: React.Ref<HTMLDivElement>
  needsOffsetForChevron?: boolean
  contentClassName?: string
}

function LinkContent({
  children,
  tail,
  tailClassName,
  ellipsisRef,
  needsOffsetForChevron,
  contentClassName,
}: InctiveLinkProps) {
  return (
    <>
      <div
        className={cn(
          styles.content,
          {
            [styles.contentOffset]: needsOffsetForChevron,
          },
          contentClassName,
        )}
        ref={ellipsisRef}
      >
        {children}
      </div>
      {tail != null ? (
        <div className={cn(styles.tail, tailClassName)} data-test-sidebar-link={'tail'}>
          {tail}
        </div>
      ) : null}
    </>
  )
}

export default function SidebarLink({
  children,
  tail,
  className,
  tailClassName,
  ellipsisRef,
  needsOffsetForChevron,
  contentClassName,
  ...htmlProps
}: ActiveLinkProps) {
  return (
    <Link
      className={cn(styles.link, styles.activeLink, className)}
      data-test-sidebar-link={'base'}
      {...htmlProps}
    >
      <LinkContent
        ellipsisRef={ellipsisRef}
        tail={tail}
        tailClassName={tailClassName}
        needsOffsetForChevron={needsOffsetForChevron}
        contentClassName={contentClassName}
      >
        {children}
      </LinkContent>
    </Link>
  )
}

export function InactiveSidebarLink({
  children,
  tail,
  className,
  ellipsisRef,
  contentClassName,
  ...htmlProps
}: InctiveLinkProps) {
  return (
    <div className={cn(styles.link, className)} data-test-sidebar-link={'base'} {...htmlProps}>
      <LinkContent tail={tail} ellipsisRef={ellipsisRef} contentClassName={contentClassName}>
        {children}
      </LinkContent>
    </div>
  )
}
