import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classnames from 'classnames'

import {usePermission} from '../../../hooks/usePermission'
import {Permission, ROOT_PROJECT_ID} from '../../../types'
import {noop} from '../../../utils/empty'

import type {Props} from './FavoriteStar.types'

import styles from './FavoriteStar.module.css'

function FavoriteStar({
  className,
  emptyClassName = '',
  iconWrapperClassName,
  isStarred,
  showEmpty = true,
  onStar = noop,
  onMouseEnter,
  onMouseLeave,
  title,
}: Props) {
  const isStarrable = usePermission(Permission.CHANGE_OWN_PROFILE, ROOT_PROJECT_ID)
  const classes = classnames(className, emptyClassName, {
    [styles.invisible]: !showEmpty && !isStarred,
    [styles.starred]: isStarred,
  })

  if (!isStarrable) {
    return null
  }

  const defaultTitle = isStarred ? 'Remove from favorites' : 'Add to favorites'
  return (
    <IconButton
      onClick={onStar}
      icon={isStarred ? 'star-filled' : 'star-empty'}
      className={classes}
      iconClassName={iconWrapperClassName}
      title={title ?? defaultTitle}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
      data-test="overview-star"
      aria-label={defaultTitle}
    />
  )
}

export default FavoriteStar
