import textIcon from '@jetbrains/icons/text.svg'
import Icon from '@jetbrains/ring-ui-built/components/icon/icon'
import cn from 'classnames'
import * as React from 'react'
import {useRef} from 'react'

import styles from '../../../../common/Sidebar/SidebarItem/SidebarItem.module.css'
import SidebarLink from '../../../../common/Sidebar/SidebarLink/SidebarLink'
import type {VirtualizedTreeNodeProps} from '../../../../common/VirtualizedTree/VirtualizedTree'
import VirtualizedTreeItem from '../../../../common/VirtualizedTree/VirtualizedTreeItem/VirtualizedTreeItem'
import VirtualizedTreeOverlayItem from '../../../../common/VirtualizedTree/VirtualizedTreeOverlayItem/VirtualizedTreeOverlayItem'
import type {AgentsPagesCanViewAgentDetailsFragment$key} from '../../__generated__/AgentsPagesCanViewAgentDetailsFragment.graphql'
import type {AgentsTreeItemType} from '../AgentsSidebar.types'
import {
  AgentTreeItemType,
  AgentTreeTitleType,
  UNAUTHORIZED_AGENTS_SELECTION_ID,
} from '../AgentsSidebar.types'
import DisconnectedAgentsCounter from '../DisconnectedAgentsCounter/DisconnectedAgentsCounter'
import AgentsSidebarEditFavorite from '../EditFavorite/AgentsSidebarEditFavorite'
import {ALL_AGENTS_SELECTION_ID} from '../selectors/pipelines/pipelinesMatchingTree'
import Title from '../Title/Title'

import Agent from './Agent/Agent'
import AgentFolder from './AgentFolder/AgentFolder'
import AgentPool from './AgentPool/AgentPool'
import AgentSelectionCounter from './AgentSelectionCounter/AgentSelectionCounter'
import {NO_CHEVRON_POOLS_OFFSET} from './AgentSidebarItem.consts'
import AgentsOverview from './AgentsOverview/AgentsOverview'
import AgentType from './AgentType/AgentType'

import itemStyles from './AgentsSidebarItem.module.css'

type Props = VirtualizedTreeNodeProps &
  AgentsTreeItemType & {
    itemKey: string
    className?: string | null | undefined
    setExpandState: (item: AgentsTreeItemType, expanded: boolean) => void
    dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
    hasFavoritePools?: boolean
  }
export const INDEX_ATTRIBUTE = 'data-index'
const popupHtmlProps = {
  trapFocus: false,
}

function AgentInternal({
  ellipsisRef,
  item,
  handleToggleExpandItem,
  dataKey,
  active,
  popupMode,
}: {
  ellipsisRef?: React.Ref<HTMLDivElement>
  item: AgentsTreeItemType
  handleToggleExpandItem: () => void
  dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
  active: boolean
  popupMode?: boolean
}) {
  return (
    <>
      {item.type === AgentTreeItemType.POOL ? (
        <AgentPool
          className={cn(styles.hoverableLink, {[styles.popup]: popupMode})}
          {...item}
          ellipsisRef={ellipsisRef}
        />
      ) : null}
      {item.type === AgentTreeItemType.AGENT_TYPE ? (
        <AgentType
          className={cn(styles.hoverableLink, {[styles.popup]: popupMode})}
          {...item}
          dataKey={dataKey}
          ellipsisRef={ellipsisRef}
          popupMode={popupMode}
        />
      ) : null}
      {item.type === AgentTreeItemType.AGENT ? (
        <Agent
          className={cn(styles.hoverableLink, {[styles.popup]: popupMode})}
          {...item}
          dataKey={dataKey}
          ellipsisRef={ellipsisRef}
        />
      ) : null}
      {item.type === AgentTreeItemType.FOLDER ? (
        <AgentFolder
          className={cn(styles.hoverableLink, {[styles.popup]: popupMode})}
          onToggleExpand={handleToggleExpandItem}
          {...item}
          ellipsisRef={ellipsisRef}
        />
      ) : null}
      {item.type === AgentTreeItemType.OVERVIEW ? (
        <AgentsOverview
          className={cn(styles.hoverableLink, {
            [styles.activeItem]: active,
          })}
          {...item}
        />
      ) : null}
    </>
  )
}
const AgentsSidebarItem: React.ComponentType<Props> = React.memo(function AgentsSidebarItem({
  className,
  setExpandState,
  index,
  style,
  height,
  width,
  indent,
  itemKey,
  parent,
  cache,
  dataKey,
  hasFavoritePools,
  ...rest
}) {
  const item: AgentsTreeItemType = rest
  const expandable = 'expandable' in item && item.expandable
  const containsActive = 'containsActive' in item && item.containsActive
  const ellipsisRef = useRef<HTMLDivElement>(null)

  const expanded = expandable && item.expanded
  const active =
    (item.type !== AgentTreeItemType.TITLE && item.active) ||
    (expanded !== true && expandable && containsActive)

  const handleToggleExpandItem = React.useCallback(() => {
    setExpandState(item, !expanded)
  }, [item, expanded, setExpandState])
  const wrapperHtmlProps = React.useMemo(
    () => ({
      tabIndex: 0,
      [INDEX_ATTRIBUTE]: index,
    }),
    [index],
  )

  switch (item.type) {
    case AgentTreeItemType.TITLE:
      return (
        <VirtualizedTreeItem
          containerClassName={itemStyles.container}
          className={cn(className, styles.item, itemStyles.title, itemStyles.favoriteTitle)}
          wrapperClassName={styles.itemWrapper}
          contentClassName={itemStyles.favorite}
          style={style}
          indent={indent}
        >
          <Title {...item} />
          {item.id === AgentTreeTitleType.FAVORITE && hasFavoritePools && (
            <AgentsSidebarEditFavorite className={itemStyles.favoriteButton} />
          )}
        </VirtualizedTreeItem>
      )

    case AgentTreeItemType.FAVORITE_LINK:
      const count = item.disconnectedCount ?? 0
      return (
        <VirtualizedTreeItem
          className={cn(className, styles.item, styles.hoverableItem, {
            [styles.activeItem]: active,
          })}
          wrapperClassName={cn(styles.itemWrapper, styles.selectHoverFocus)}
          style={style}
          indent={indent}
          expandable={expandable}
          wrapperHtmlProps={wrapperHtmlProps}
        >
          <SidebarLink
            to={item.to}
            className={styles.hoverableLink}
            tail={count > 0 && <DisconnectedAgentsCounter count={count} />}
            tabIndex={-1}
            aria-label={item.title}
            needsOffsetForChevron
          >
            <div className={styles.overview}>
              <Icon glyph={textIcon} className={styles.icon} />
              <span>{item.title}</span>
            </div>
          </SidebarLink>
        </VirtualizedTreeItem>
      )

    case AgentTreeItemType.SELECTION:
      const tail =
        ALL_AGENTS_SELECTION_ID !== item.id && (item.count > 0 || item.disconnectedCount > 0) ? (
          <AgentSelectionCounter item={item} />
        ) : null

      return (
        <VirtualizedTreeItem
          containerClassName={itemStyles.container}
          className={cn(className, styles.item, itemStyles.title, itemStyles.selection)}
          wrapperClassName={styles.itemWrapper}
          contentClassName={cn(itemStyles.favorite, itemStyles.nonClickableHeader)}
          style={style}
          indent={indent + (item.expandable ? 0 : NO_CHEVRON_POOLS_OFFSET)}
          expanded={expanded}
          expandable={item.expandable}
          onToggleExpand={handleToggleExpandItem}
          level={0}
        >
          <Title {...item} handleChevronClick={handleToggleExpandItem} />
          {tail && <div className={itemStyles.tail}>{tail} </div>}
          {!hasFavoritePools && item.id !== UNAUTHORIZED_AGENTS_SELECTION_ID && (
            <AgentsSidebarEditFavorite className={itemStyles.favoriteButton} />
          )}
        </VirtualizedTreeItem>
      )

    default:
      return (
        <VirtualizedTreeOverlayItem
          className={cn(className, styles.item, styles.hoverableItem)}
          activeClassName={cn(styles.activeItem)}
          hoveredClassName={styles.hoveredItem}
          wrapperClassName={cn(styles.itemWrapper, styles.selectHoverFocus)}
          active={active}
          expanded={expanded}
          onToggleExpand={handleToggleExpandItem}
          popupHtmlProps={popupHtmlProps}
          itemType={item.type}
          itemKey={itemKey}
          wrapperHtmlProps={wrapperHtmlProps}
          index={index}
          style={style}
          height={height}
          width={width}
          ellipsisRef={ellipsisRef}
          indent={indent}
          parent={parent}
          cache={cache}
          expandable={expandable}
          popupContent={
            <AgentInternal
              item={item}
              handleToggleExpandItem={handleToggleExpandItem}
              dataKey={dataKey}
              active={active}
              popupMode
            />
          }
        >
          <AgentInternal
            item={item}
            ellipsisRef={ellipsisRef}
            handleToggleExpandItem={handleToggleExpandItem}
            dataKey={dataKey}
            active={active}
          />
        </VirtualizedTreeOverlayItem>
      )
  }
})

export default AgentsSidebarItem
