import type {IconType} from '@jetbrains/ring-ui-built/components/icon/icon'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import type {HTMLAttributes} from 'react'

import MatchingItem from '../../../../common/MatchingItem/MatchingItem'

type Props = HTMLAttributes<HTMLDivElement> & {
  title?: string
  matching?: boolean
  searchQuery?: string
  className?: string
  icon?: IconType | string | null
}
export default function LinearAgentType({
  title,
  className,
  searchQuery,
  icon,
  ...htmlProps
}: Props) {
  return (
    <span className={className} {...htmlProps}>
      <SvgIcon icon={icon ?? 'cloud'} />{' '}
      <MatchingItem searchQuery={searchQuery}>{title}</MatchingItem>
    </span>
  )
}
