import type {KeyValue} from '@jetbrains/teamcity-ui/dist/utils'
import cn from 'classnames'
import * as React from 'react'
import {useLocation} from 'react-router'

import {useQueryParam} from '../../../../../../hooks/routes'
import {getAgentTypeHref, matchRoute, Routes} from '../../../../../../routes'
import SidebarLink, {
  InactiveSidebarLink,
} from '../../../../../common/Sidebar/SidebarLink/SidebarLink'
import type {AgentsPagesCanViewAgentDetailsFragment$key} from '../../../__generated__/AgentsPagesCanViewAgentDetailsFragment.graphql'
import {useCanViewAgentDetails} from '../../../AgentsPages.hooks'
import LinearAgentType from '../../../components/LinearAgentType/LinearAgentType'
import type {AgentsTreeItemAgentType} from '../../AgentsSidebar.types'
import {AgentTreeItemCategory} from '../../AgentsSidebar.types'
import BusyAgentsCounter from '../../BusyAgentsCounter/BusyAgentsCounter'
import DisconnectedAgentsCounter from '../../DisconnectedAgentsCounter/DisconnectedAgentsCounter'
import {getAgentsTreeSearchState} from '../../selectors/getExpand'

import styles from './AgentType.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = AgentsTreeItemAgentType & {
  className?: string | undefined
  style?: KeyValue<string, string | number>
  dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
  ellipsisRef?: React.Ref<HTMLDivElement>
  popupMode?: boolean
}
export default React.memo(function AgentType({
  id,
  title,
  count,
  busyCount,
  disconnectedCount,
  className,
  style,
  category,
  dataKey,
  icon,
  ellipsisRef,
  expandable,
  popupMode = false,
}: Props) {
  const canViewAgentDetails = useCanViewAgentDetails(dataKey)
  const tail =
    disconnectedCount > 0 ? <DisconnectedAgentsCounter count={disconnectedCount} /> : null
  let agentTypeHref = getAgentTypeHref(id, category === AgentTreeItemCategory.MAIN)
  const location = useLocation()
  const tab = useQueryParam('tab')

  if (matchRoute(Routes.CLOUD_IMAGE, location.pathname) != null && tab != null) {
    agentTypeHref = `${agentTypeHref}?tab=${tab}`
  }

  const {searchQuery} = useAppSelector(getAgentsTreeSearchState)
  const linkContent = (
    <>
      <LinearAgentType title={title} searchQuery={searchQuery} icon={icon} />
      <BusyAgentsCounter
        busyCount={busyCount}
        disconnectedCount={disconnectedCount}
        count={count}
      />
    </>
  )
  const linkProps = {className, style, tail}

  const classNames = cn(linkProps.className, {[styles.offset]: !expandable && !popupMode})
  return canViewAgentDetails ? (
    <SidebarLink
      to={agentTypeHref}
      tabIndex={-1}
      ellipsisRef={ellipsisRef}
      {...linkProps}
      className={classNames}
      contentClassName={cn({[styles.popup]: popupMode})}
    >
      {linkContent}
    </SidebarLink>
  ) : (
    <InactiveSidebarLink
      ellipsisRef={ellipsisRef}
      contentClassName={cn({[styles.popup]: popupMode})}
      {...linkProps}
    >
      {linkContent}
    </InactiveSidebarLink>
  )
})
