import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import type {KeyValue} from '@jetbrains/teamcity-ui/dist/utils'
import classNames from 'classnames'
import * as React from 'react'
import {useLocation} from 'react-router'

import {useQueryParam} from '../../../../../../hooks/routes'
import {Routes, getAgentHref, matchRoute} from '../../../../../../routes'
import SidebarLink, {
  InactiveSidebarLink,
} from '../../../../../common/Sidebar/SidebarLink/SidebarLink'
import type {AgentsPagesCanViewAgentDetailsFragment$key} from '../../../__generated__/AgentsPagesCanViewAgentDetailsFragment.graphql'
import {useCanViewAgentDetails} from '../../../AgentsPages.hooks'
import LinearAgent from '../../../components/LinearAgent/LinearAgent'
import type {AgentsTreeItemAgent} from '../../AgentsSidebar.types'
import {AgentTreeItemCategory} from '../../AgentsSidebar.types'
import {getAgentsTreeSearchState} from '../../selectors/getExpand'

import styles from './Agent.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = AgentsTreeItemAgent & {
  className?: string
  style?: KeyValue<string, string | number>
  dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
  ellipsisRef?: React.Ref<HTMLDivElement>
}
function Agent({
  id,
  title,
  busy,
  connected,
  enabled,
  authorized,
  cloud,
  matching,
  className,
  style,
  osType,
  category,
  dataKey,
  ellipsisRef,
}: Props) {
  const canViewAgentDetails = useCanViewAgentDetails(dataKey)
  let tail: React.ReactNode = authorized && busy !== true ? 'idle' : null

  if (connected !== true) {
    tail = (
      <React.Fragment>
        {tail && <span className={styles.idle}>{tail}</span>}
        <Tooltip title={'Disconnected'}>
          <SvgIcon
            className={styles.disconnectedIcon}
            icon="disconnected"
            title="disconnected"
            data-test-sidebar-agent={'disconnected-icon'}
          />
        </Tooltip>
      </React.Fragment>
    )
  } else if (enabled !== true) {
    tail = cloud ? 'maintenance' : 'disabled'
  }

  let agentHref = getAgentHref(id, category === AgentTreeItemCategory.MAIN)
  const location = useLocation()
  const tab = useQueryParam('tab')

  if (matchRoute(Routes.AGENT, location.pathname) != null && tab != null) {
    agentHref = `${agentHref}?tab=${tab}`
  }

  const {searchQuery} = useAppSelector(getAgentsTreeSearchState)
  const linkContent = (
    <LinearAgent
      title={title}
      osType={osType}
      enabled={enabled}
      cloud={cloud}
      matching={matching}
      searchQuery={searchQuery}
    />
  )
  const linkProps = {
    className: classNames(className, {[styles.disconnected]: !connected}),
    style,
    ['aria-label']: title,
    tail,
  }

  //agents are not expandable -
  // therefore, they need an extra offset to cover for elements with chevron
  return canViewAgentDetails ? (
    <SidebarLink
      to={agentHref}
      tabIndex={-1}
      {...linkProps}
      ellipsisRef={ellipsisRef}
      className={styles.offset}
    >
      {linkContent}
    </SidebarLink>
  ) : (
    <InactiveSidebarLink ellipsisRef={ellipsisRef} {...linkProps} className={styles.offset}>
      {linkContent}
    </InactiveSidebarLink>
  )
}
export default React.memo(Agent)
